using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.InputSystem;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class OnLookTest {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/Diagnostics/OnLook_20261109/"));static InputAction action;static Transform player,pivot;static MonoBehaviour look,presenter;static Quaternion yaw,pitch;static float storedPitch;static int startFrame,events;static double startTime;static Vector2 lastValue;static InputSettings.BackgroundBehavior bg;static InputSettings.EditorInputBehaviorInPlayMode eb;static bool running;static System.Collections.Generic.List<string> errors=new System.Collections.Generic.List<string>();
 static FieldInfo Field(object c,string name)=>c.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic);
 public static object Prepare(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");SessionState.SetBool("OnLookDiag.Background",Application.runInBackground);Application.runInBackground=true;return new{mouseEnabled=Mouse.current?.enabled,scene=SceneManager.GetActiveScene().path};}
 public static object Begin(){if(!Application.isPlaying)throw new Exception("Play required");if(!Mouse.current.enabled)throw new Exception("Mouse disabled");var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));player=root.transform;look=root.GetComponentsInChildren<MonoBehaviour>().Single(c=>c.GetType().Name=="PlayerLook");presenter=root.GetComponentsInChildren<MonoBehaviour>().Single(c=>c.GetType().Name=="PlayerPresenter");pivot=(Transform)Field(look,"cameraRoot").GetValue(look);yaw=player.rotation;pitch=pivot.localRotation;storedPitch=(float)Field(look,"pitchAngle").GetValue(look);action=root.GetComponent<PlayerInput>().actions.FindAction("Player/Look",true);if(!action.enabled||!look.enabled||!presenter.enabled)throw new Exception("Look chain disabled");bg=InputSystem.settings.backgroundBehavior;eb=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();startFrame=Time.frameCount;startTime=EditorApplication.timeSinceStartup;events=0;running=true;action.performed+=Read;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;AssemblyReloadEvents.beforeAssemblyReload+=Cancel;EditorApplication.playModeStateChanged+=Mode;return new{frame=startFrame,action=action.name,action.enabled,mouseEnabled=Mouse.current.enabled};}
 static void Read(InputAction.CallbackContext c){events++;lastValue=c.ReadValue<Vector2>();}
 static void Log(string m,string st,LogType t){if(t==LogType.Error||t==LogType.Exception)errors.Add(m);}
 static void Mode(PlayModeStateChange s){if(s==PlayModeStateChange.ExitingPlayMode)Cancel();}static void Cancel(){if(running)Finish(false);}
 static void Tick(){try{if(!Application.isPlaying){Finish(false);return;}EditorApplication.QueuePlayerLoopUpdate();int elapsed=Time.frameCount-startFrame;if(elapsed<12)InputSystem.QueueDeltaStateEvent(Mouse.current.delta,new Vector2(6,3));if(elapsed>35||EditorApplication.timeSinceStartup-startTime>10)Finish(true);}catch{Finish(false);throw;}}
 static void Finish(bool complete){running=false;EditorApplication.update-=Tick;AssemblyReloadEvents.beforeAssemblyReload-=Cancel;EditorApplication.playModeStateChanged-=Mode;Application.logMessageReceived-=Log;action.performed-=Read;var result=new{complete,frames=Time.frameCount-startFrame,events,lastValue=lastValue.ToString(),yawChange=player?Quaternion.Angle(yaw,player.rotation):0,pitchChange=pivot?Quaternion.Angle(pitch,pivot.localRotation):0,mouseEnabled=Mouse.current.enabled,errors};try{File.WriteAllText(H+"look_test.json",JsonConvert.SerializeObject(result,Formatting.Indented));}finally{InputSystem.settings.backgroundBehavior=bg;InputSystem.settings.editorInputBehaviorInPlayMode=eb;if(player)player.rotation=yaw;if(pivot)pivot.localRotation=pitch;if(look)Field(look,"pitchAngle").SetValue(look,storedPitch);if(presenter)Field(presenter,"lookInput").SetValue(presenter,Vector2.zero);}}
 public static object Restore(){if(Application.isPlaying)throw new Exception("Exit Play first");Application.runInBackground=SessionState.GetBool("OnLookDiag.Background",false);return new{mouseEnabled=Mouse.current.enabled,Application.runInBackground,scene=SceneManager.GetActiveScene().path,dirty=SceneManager.GetActiveScene().isDirty};}
}
